use std::sync::Arc;

use common::{Schema, UniqueKey};

use super::{AbstractPlanNode, PlanNode, expect_children};

/// Creates a table in the catalog, with its primary key index if it has a
/// primary key and a unique index for each UNIQUE constraint. Produces no
/// rows.
#[derive(Clone, Debug)]
pub struct CreateTablePlan {
    /// Always empty.
    output_schema: Schema,
    table_name: String,
    /// The new table's columns.
    table_schema: Schema,
    /// The primary key columns, in key order. Empty for no primary key.
    primary_key: Vec<String>,
    /// The `GENERATED BY DEFAULT AS IDENTITY` columns.
    identity: Vec<String>,
    unique: Vec<UniqueKey>,
    /// Does nothing if a table of that name exists.
    if_not_exists: bool,
}

impl CreateTablePlan {
    pub fn new(
        table_name: impl Into<String>,
        table_schema: Schema,
        primary_key: Vec<String>,
    ) -> Self {
        Self {
            output_schema: Schema::default(),
            table_name: table_name.into(),
            table_schema,
            primary_key,
            identity: Vec::new(),
            unique: Vec::new(),
            if_not_exists: false,
        }
    }

    pub fn with_if_not_exists(mut self, if_not_exists: bool) -> Self {
        self.if_not_exists = if_not_exists;
        self
    }

    pub fn if_not_exists(&self) -> bool {
        self.if_not_exists
    }

    pub fn with_identity(mut self, identity: Vec<String>) -> Self {
        self.identity = identity;
        self
    }

    pub fn with_unique(mut self, unique: Vec<UniqueKey>) -> Self {
        self.unique = unique;
        self
    }

    pub fn table_name(&self) -> &str {
        &self.table_name
    }

    pub fn table_schema(&self) -> &Schema {
        &self.table_schema
    }

    pub fn primary_key(&self) -> &[String] {
        &self.primary_key
    }

    pub fn identity(&self) -> &[String] {
        &self.identity
    }

    pub fn unique(&self) -> &[UniqueKey] {
        &self.unique
    }
}

impl PlanNode for CreateTablePlan {
    fn get_output_schema(&self) -> &Schema {
        &self.output_schema
    }

    fn get_children(&self) -> &[Arc<AbstractPlanNode>] {
        &[]
    }

    fn clone_with_children(&self, children: Vec<Arc<AbstractPlanNode>>) -> AbstractPlanNode {
        expect_children("CreateTable", children, 0);
        self.clone().into()
    }
}
